function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  let limit: number | undefined;
  let before: {updatedAt: string | number; sessionId: string} | undefined;

  if (message.limit !== undefined) {
    if (
      typeof message.limit !== 'number' ||
      !Number.isInteger(message.limit) ||
      message.limit < 1 ||
      message.limit > 200
    ) {
      return {valid: false, error: 'list_sessions limit must be an integer 1–200'};
    }
    limit = message.limit;
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'list_sessions before must be an object'};
    }

    const cursorObj = message.before as Record<string, unknown>;

    if (typeof cursorObj.sessionId !== 'string') {
      return {valid: false, error: 'list_sessions before.sessionId must be a string'};
    }
    if (cursorObj.sessionId.length < 1 || cursorObj.sessionId.length > 128) {
      return {valid: false, error: 'list_sessions before.sessionId must be 1–128 chars'};
    }

    const updatedAt = cursorObj.updatedAt;
    if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
      return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
    }

    if (typeof updatedAt === 'string') {
      const timestamp = Date.parse(updatedAt);
      if (isNaN(timestamp)) {
        return {valid: false, error: 'list_sessions before.updatedAt is not a valid date'};
      }
    } else if (!Number.isFinite(updatedAt)) {
      return {valid: false, error: 'list_sessions before.updatedAt must be finite'};
    }

    before = {updatedAt, sessionId: cursorObj.sessionId};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit,
      before,
    },
  };
}

