  if (message.limit !== undefined) {
    if (
      typeof message.limit !== 'number' ||
      !Number.isInteger(message.limit) ||
      message.limit < 1 ||
      message.limit > 200
    ) {
      return {valid: false, error: 'list_sessions limit must be an integer 1–200'};
    }
    limit = message.limit;
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'list_sessions before must be an object'};
    }

    const cursorObj = message.before as Record<string, unknown>;

