import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitValidation = validateLimit(message.limit);
  if (limitValidation) return limitValidation;

  const beforeValidation = validateBefore(message.before);
  if (beforeValidation) return beforeValidation;

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: message.limit as number | undefined,
      before: formatBefore(message.before),
    },
  };
}

function isValidLimit(limit: unknown): limit is number {
  return typeof limit === 'number' && Number.isInteger(limit) && limit >= 1 && limit <= 200;
}

function validateLimit(limit: unknown): ValidationResult | undefined {
  if (limit === undefined) return undefined;
  if (isValidLimit(limit)) return undefined;
  return {valid: false, error: 'list_sessions limit must be an integer 1–200'};
}

function isValidCursor(before: unknown): before is {sessionId: string; updatedAt: string | number} {
  if (typeof before !== 'object' || before === null) return false;

  const cursor = before as Record<string, unknown>;
  const {sessionId, updatedAt} = cursor;

  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > 128) return false;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;

  if (typeof updatedAt === 'string') {
    const timestamp = Date.parse(updatedAt);
    return !isNaN(timestamp);
  }

  return Number.isFinite(updatedAt);
}

function validateBefore(before: unknown): ValidationResult | undefined {
  if (before === undefined) return undefined;

  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const cursor = before as Record<string, unknown>;

  if (typeof cursor.sessionId !== 'string') {
    return {valid: false, error: 'list_sessions before.sessionId must be a string'};
  }

  if (cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
    return {valid: false, error: 'list_sessions before.sessionId must be 1–128 chars'};
  }

  const {updatedAt} = cursor;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a string or number'};
  }

  if (typeof updatedAt === 'string') {
    const timestamp = Date.parse(updatedAt);
    if (isNaN(timestamp)) {
      return {valid: false, error: 'list_sessions before.updatedAt is not a valid date'};
    }
  } else if (!Number.isFinite(updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be finite'};
  }

  return undefined;
}

function formatBefore(before: unknown): {updatedAt: string | number; sessionId: string} | undefined {
  if (before === undefined) return undefined;
  const cursor = before as {sessionId: string; updatedAt: string | number};
  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
}

