    const frames = await connectAndSettle(`${base}?sessionId=known`);

    expect({replayed: upserts(frames)[1], stored: known.entries[1]}).toEqual({
      replayed: {index: 1, entry: {...HALF_ANSWER, isStreaming: false, truncated: true}},
