    const {base} = await startEngine(new InMemorySessionStore());

    const frames = await connectAndSettle(`${base}/undefined`);

    expect(frames[0]).toMatchObject({type: 'connected', sessionId: expect.stringMatching(/^[0-9a-f-]{36}$/)});
  });

