    const store = storeWith([['known', 'u1', '2026-09-30T08:00:00.000Z']]);
    const {auth, base} = await startEngine(store, LATEST_ON);

    const asked = await connectAndSettle(`${base}?new=1`);
    auth.userId = 'u2';
    const firstVisit = await connectAndSettle(base);

